using MediatR;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using TheMathAndScienceAcademy.Api.Authorization;using TheMathAndScienceAcademy.Application.Features.Teachers;using TheMathAndScienceAcademy.Application.Abstractions;
namespace TheMathAndScienceAcademy.Api.Controllers;
[ApiController,Authorize,Route("api/teachers")] public class TeachersController:ControllerBase{readonly IMediator _m;public TeachersController(IMediator m)=>_m=m;[HttpGet,HasPermission("teacher.view")]public async Task<IActionResult> Get()=>Ok(await _m.Send(new GetTeachersQuery()));[HttpGet("me"),HasPermission("teacher.self-view")]public async Task<IActionResult> Me()=>Ok(await _m.Send(new GetMyTeacherQuery()));[HttpGet("{id:guid}"),HasPermission("teacher.view")]public async Task<IActionResult> Get(Guid id)=>Ok(await _m.Send(new GetTeacherQuery(id)));[HttpPost,HasPermission("teacher.create")]public async Task<IActionResult> Create(CreateTeacherCommand c)=>Ok(await _m.Send(c));[HttpPut("{id:guid}"),HasPermission("teacher.update")]public async Task<IActionResult> Update(Guid id,UpdateTeacherCommand c){c.Id=id;return Ok(await _m.Send(c));}[HttpDelete("{id:guid}"),HasPermission("teacher.delete")]public async Task<IActionResult> Delete(Guid id)=>Ok(await _m.Send(new DeleteTeacherCommand(id)));[HttpPost("{id:guid}/create-account"),HasPermission("teacher.create-account")]public async Task<IActionResult> Account(Guid id)=>Ok(await _m.Send(new CreateTeacherAccountCommand(id)));[HttpPost("{id:guid}/resend-credentials"),HasPermission("teacher.resend-credentials")]public async Task<IActionResult> Resend(Guid id)=>Ok(await _m.Send(new ResendTeacherCredentialsCommand(id)));[HttpPost("{id:guid}/photo"),Consumes("multipart/form-data"),HasPermission("teacher.update")]public async Task<IActionResult> UploadPhoto(Guid id,IFormFile file){await using var stream=file.OpenReadStream();return Ok(await _m.Send(new UploadTeacherPhotoCommand(id,new ProfilePhotoUpload(stream,file.ContentType,file.Length))));}[HttpGet("{id:guid}/photo"),HasPermission("teacher.view")]public async Task<IActionResult> Photo(Guid id)=>await SendPhoto(new GetTeacherPhotoQuery(id));[HttpGet("me/photo"),HasPermission("teacher.self-view")]public async Task<IActionResult> MyPhoto()=>await SendPhoto(new GetMyTeacherPhotoQuery());[HttpDelete("{id:guid}/photo"),HasPermission("teacher.update")]public async Task<IActionResult> DeletePhoto(Guid id)=>Ok(await _m.Send(new DeleteTeacherPhotoCommand(id)));private async Task<IActionResult> SendPhoto(IRequest<ApiResponse<ProfilePhotoContent>> query){var result=await _m.Send(query);return !result.Success||result.Data is null?NotFound(result):File(result.Data.Content,result.Data.ContentType);}}
